/// Known clipboard format/UTI/MIME markers set by password managers or OS privacy APIs.
pub const PRIVACY_MARKER_FORMATS: &[&str] = &[
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "ExcludeClipboardContentFromMonitorProcessing",
    "CanIncludeInClipboardHistory",
    "x-kde-passwordManagerHint",
];

/// Returns `true` if any clipboard format/type indicates concealed, transient, or password-manager data.
///
/// Covers:
/// - macOS: `org.nspasteboard.TransientType`, `org.nspasteboard.ConcealedType`,
///   `org.nspasteboard.AutoGeneratedType`, `com.agilebits.onepassword`
/// - Windows: `ExcludeClipboardContentFromMonitorProcessing`, `CanIncludeInClipboardHistory`
/// - Linux: `x-kde-passwordManagerHint`
pub fn has_password_manager_marker(formats: &[String]) -> bool {
    formats.iter().any(|fmt| is_privacy_marker(fmt))
}

/// Checks whether a single clipboard format/UTI/MIME identifier is a password-manager privacy marker.
pub fn is_privacy_marker(format: &str) -> bool {
    let normalized = format.trim().to_ascii_lowercase();
    if normalized.is_empty() {
        return false;
    }

    matches!(
        normalized.as_str(),
        "org.nspasteboard.transienttype"
            | "org.nspasteboard.concealedtype"
            | "org.nspasteboard.autogeneratedtype"
            | "com.agilebits.onepassword"
            | "excludeclipboardcontentfrommonitorprocessing"
            | "canincludeinclipboardhistory"
            | "canincludeinclipboardhistory=0"
            | "canincludeinclipboardhistory:0"
            | "x-kde-passwordmanagerhint"
            | "x-kde-passwordmanagerhint=secret"
            | "x-kde-passwordmanagerhint=hidden"
            | "x-kde-passwordmanagerhint=true"
            | "x-kde-passwordmanagerhint=1"
    ) || normalized.starts_with("com.agilebits.onepassword.")
}
